<?php
/** How search engines work: crawling, indexing, ranking, robots.txt and sitemaps, technical SEO. */

return [
    'id' => 'crawler', 'family' => 'search', 'after' => 'html-base', 'categories' => ['frontend', 'backend'],
    'title' => L('Crawler: come funzionano i motori di ricerca', 'Crawlers: how search engines work'), 'short' => L('Crawler', 'Crawlers'), 'level' => L('Base', 'Basics'),
    'desc' => L('Dalla scansione all’indice al ranking: come un crawler visita il web, che cosa leggono i motori di ricerca, robots.txt, sitemap e le basi della SEO tecnica.', 'From crawling to the index to ranking: how a crawler visits the web, what search engines read, robots.txt, sitemaps and the basics of technical SEO.'),
    'lessons' => [
        lesson('crawling', L('Scansione: il crawler al lavoro', 'Crawling: the crawler at work'), [
            P('Un motore di ricerca lavora in tre fasi: **scansione** (crawling), **indicizzazione** e **posizionamento** (ranking). Il **crawler** (o spider, o bot, come Googlebot o Bingbot) è un programma che scarica una pagina, ne estrae i link e li mette in una coda di indirizzi da visitare: così, link dopo link, scopre il web.', 'A search engine works in three phases: **crawling**, **indexing** and **ranking**. The **crawler** (or spider, or bot, such as Googlebot or Bingbot) is a program that downloads a page, extracts its links and adds them to a queue of addresses to visit: that way, link after link, it discovers the web.'),
            C('coda = [pagina iniziale]
finché coda non è vuota:
    url = coda.estrai()
    se già visitato o vietato da robots.txt: salta
    html = scarica(url)
    salva(html) per l’indicizzazione
    per ogni link in html: coda.aggiungi(link)', 'text'),
            P('Un crawler educato rispetta il file `robots.txt`, non sovraccarica i server (limita le richieste al secondo) e gestisce un **budget di scansione**: su siti enormi non visita tutto, ma privilegia le pagine importanti e aggiornate spesso. Le pagine senza nessun link in entrata (**pagine orfane**) rischiano di non essere mai trovate.', 'A polite crawler respects the `robots.txt` file, does not overload servers (it limits requests per second) and manages a **crawl budget**: on huge sites it does not visit everything, but favours important and frequently updated pages. Pages with no inbound links at all (**orphan pages**) risk never being found.'),
        ], [
            Q('c1', L('Qual è l’ordine delle fasi di un motore di ricerca?', 'What is the order of a search engine’s phases?'), [L('Scansione, indicizzazione, ranking', 'Crawling, indexing, ranking'), L('Ranking, scansione, indicizzazione', 'Ranking, crawling, indexing'), L('Indicizzazione, ranking, scansione', 'Indexing, ranking, crawling'), L('Scansione, ranking, indicizzazione', 'Crawling, ranking, indexing')], 0, L('Prima si scopre, poi si archivia, poi si ordina.', 'First discover, then store, then sort.')),
            Q('c2', L('Come scopre nuove pagine un crawler?', 'How does a crawler discover new pages?'), [L('Seguendo i link delle pagine già visitate', 'By following links in pages it already visited'), L('Leggendo la mente dei webmaster', 'By reading webmasters’ minds'), L('Provando indirizzi a caso', 'By trying random addresses'), L('Solo dai pagamenti dei siti', 'Only from sites’ payments')], 0, L('Il web è un grafo di link.', 'The web is a graph of links.')),
            Q('c3', L('Che cos’è una pagina orfana?', 'What is an orphan page?'), [L('Una pagina senza link in entrata', 'A page with no inbound links'), L('Una pagina senza immagini', 'A page with no images'), L('Una pagina con troppi link', 'A page with too many links'), L('Una pagina in un’altra lingua', 'A page in another language')], 0, L('Nessuno la indica, il crawler non la trova.', 'Nobody points to it, the crawler cannot find it.')),
        ], task('text', L('Scrivi i passi del ciclo di un crawler, uno per riga numerati da `1.` a `4.`: scarica, estrai i link, aggiungi alla coda, prendi il prossimo URL. Mettili nell’ordine giusto partendo da “prendi”.', 'Write the steps of a crawler loop, one per line numbered `1.` to `4.`: download, extract the links, add to the queue, take the next URL. Put them in the right order starting from “take”.'), "1. \n2. \n3. \n4. ", [re('^1\.\s*(prend|take)', L('Prima prende un URL', 'First it takes a URL')), re('^2\.\s*(scaric|download)', L('Poi scarica', 'Then it downloads')), re('^3\.\s*(estra|extract)', L('Poi estrae i link', 'Then it extracts links')), re('^4\.\s*(aggiung|add)', L('Infine li accoda', 'Finally it queues them'))], '', "1. prendi il prossimo URL dalla coda\n2. scarica la pagina\n3. estrai i link\n4. aggiungi i link alla coda"), [
            dOrder(pSort(), [L('Prendi un URL dalla coda', 'Take a URL from the queue'), L('Controlla robots.txt', 'Check robots.txt'), L('Scarica la pagina', 'Download the page'), L('Estrai i link', 'Extract the links'), L('Aggiungi i link alla coda', 'Add the links to the queue')], L('Il ciclo di un crawler.', 'A crawler’s loop.')),
            dFlash(pFlash(), [[L('Googlebot è un crawler', 'Googlebot is a crawler'), true], [L('Un crawler visita sempre ogni pagina di ogni sito', 'A crawler always visits every page of every site'), false], [L('Un crawler educato limita le richieste al secondo', 'A polite crawler limits requests per second'), true], [L('Le pagine orfane sono le più facili da trovare', 'Orphan pages are the easiest to find'), false]], L('Bot che esplorano.', 'Bots that explore.')),
        ]),
        lesson('robots', L('robots.txt, sitemap e meta robots', 'robots.txt, sitemaps and meta robots'), [
            P('Il file `robots.txt`, nella radice del sito, dice ai crawler quali percorsi **non scansionare**. È un’indicazione, non una protezione: i bot malevoli lo ignorano, e una pagina vietata può comunque comparire nei risultati se altri siti la linkano. Per i dati riservati serve un login.', 'The `robots.txt` file, at the root of the site, tells crawlers which paths **not to crawl**. It is a guideline, not protection: malicious bots ignore it, and a disallowed page may still appear in results if other sites link to it. Private data needs a login.'),
            C('User-agent: *
Disallow: /admin/
Disallow: /carrello
Allow: /admin/aiuto.html

Sitemap: https://www.esempio.it/sitemap.xml', 'text'),
            P('La **sitemap XML** elenca gli URL che vuoi far conoscere, con la data di ultima modifica: aiuta a scoprire pagine profonde o nuove. Per tenere una pagina **fuori dall’indice** si usa invece il meta tag `<meta name="robots" content="noindex">` (che il crawler deve poter leggere: non bloccarla anche in robots.txt). Con `rel="canonical"` indichi la versione principale di pagine duplicate.', 'The **XML sitemap** lists the URLs you want known, with their last modification date: it helps discover deep or new pages. To keep a page **out of the index** you use instead the meta tag `<meta name="robots" content="noindex">` (which the crawler must be able to read: do not also block it in robots.txt). With `rel="canonical"` you point to the main version of duplicate pages.'),
        ], [
            Q('r1', L('A che cosa serve `Disallow` in robots.txt?', 'What is `Disallow` for in robots.txt?'), [L('Chiede di non scansionare un percorso', 'Asks not to crawl a path'), L('Protegge il percorso con una password', 'Protects the path with a password'), L('Cancella la pagina dal server', 'Deletes the page from the server'), L('Velocizza la pagina', 'Speeds up the page')], 0, L('È un’indicazione per i bot.', 'It is a hint for bots.')),
            Q('r2', L('Come si tiene una pagina fuori dall’indice?', 'How do you keep a page out of the index?'), [L('Con il meta tag robots `noindex`', 'With the robots meta tag `noindex`'), L('Con un titolo vuoto', 'With an empty title'), L('Con una sitemap più lunga', 'With a longer sitemap'), L('Con più parole chiave', 'With more keywords')], 0, L('noindex agisce sull’indice.', 'noindex acts on the index.')),
            Q('r3', L('Che cosa contiene una sitemap XML?', 'What does an XML sitemap contain?'), [L('Gli URL da far conoscere e le loro date', 'URLs to make known and their dates'), L('Le password del sito', 'The site’s passwords'), L('Il CSS delle pagine', 'The pages’ CSS'), L('Gli indirizzi email dei visitatori', 'Visitors’ email addresses')], 0, L('Una mappa per i crawler.', 'A map for crawlers.')),
        ], task('text', L('Scrivi un robots.txt che valga per tutti i bot (`User-agent: *`), vieti `/admin/` e indichi la sitemap `https://www.esempio.it/sitemap.xml`.', 'Write a robots.txt that applies to every bot (`User-agent: *`), disallows `/admin/` and points to the sitemap `https://www.esempio.it/sitemap.xml`.'), '', [re('^User-agent:\s*\*', L('Tutti i bot', 'Every bot')), re('^Disallow:\s*/admin/', L('Vieta /admin/', 'Disallows /admin/')), re('^Sitemap:\s*https://www\.esempio\.it/sitemap\.xml', L('Indica la sitemap', 'Points to the sitemap'))], '', "User-agent: *\nDisallow: /admin/\n\nSitemap: https://www.esempio.it/sitemap.xml"), [
            dMatch(pMatch(), [['Disallow', L('Non scansionare questo percorso', 'Do not crawl this path')], ['noindex', L('Non mettere nell’indice', 'Do not put in the index')], ['Sitemap', L('Elenco degli URL da scoprire', 'List of URLs to discover')], ['canonical', L('Versione principale di un duplicato', 'Main version of a duplicate')]], L('Gli strumenti per guidare i bot.', 'The tools to guide bots.')),
            dBug(pBug(), ['User-agent: *', 'Disallow: /admin/', 'Sitemap: /sitemap.xml'], 2, 'Sitemap: https://www.esempio.it/sitemap.xml', L('La sitemap va indicata con l’URL completo.', 'The sitemap must be given as a full URL.')),
        ]),
        lesson('indexing', L('Indicizzazione: che cosa legge il motore', 'Indexing: what the engine reads'), [
            P('Dopo la scansione il motore **analizza** la pagina: il testo, il `<title>`, la meta description, i titoli `<h1>`-`<h6>`, il testo dei link, gli `alt` delle immagini, i dati strutturati. Oggi Google **esegue anche il JavaScript** (rendering), ma in una seconda passata e con limiti: i contenuti importanti è meglio averli già nell’HTML.', 'After crawling the engine **analyses** the page: the text, the `<title>`, the meta description, the `<h1>`-`<h6>` headings, link text, image `alt`s, structured data. Today Google **also runs JavaScript** (rendering), but in a second pass and with limits: important content is better already in the HTML.'),
            P('Il risultato è un **indice invertito**: per ogni parola, l’elenco delle pagine che la contengono (con posizione e importanza), come l’indice analitico in fondo a un libro. È ciò che permette di rispondere in pochi millisecondi cercando tra miliardi di pagine.', 'The result is an **inverted index**: for each word, the list of pages that contain it (with position and importance), like the index at the back of a book. That is what makes it possible to answer in a few milliseconds while searching billions of pages.'),
            C('"pizza"    → [pagina 12, pagina 87, pagina 301]
"napoli"   → [pagina 12, pagina 44]
"ricetta"  → [pagina 87, pagina 12]

ricerca "pizza napoli" → intersezione → pagina 12', 'text'),
            Tip('I **dati strutturati** (JSON-LD con il vocabolario schema.org) dicono esplicitamente che cosa c’è nella pagina, per esempio una ricetta con tempi e voti, e possono generare risultati arricchiti.', '**Structured data** (JSON-LD with the schema.org vocabulary) state explicitly what is on the page, for example a recipe with times and ratings, and can produce rich results.'),
        ], [
            Q('i1', L('Che cos’è un indice invertito?', 'What is an inverted index?'), [L('Per ogni parola, le pagine che la contengono', 'For each word, the pages that contain it'), L('Le pagine in ordine alfabetico inverso', 'Pages in reverse alphabetical order'), L('Una pagina scritta al contrario', 'A page written backwards'), L('L’elenco dei siti bannati', 'The list of banned sites')], 0, L('Come l’indice di un libro.', 'Like a book’s index.')),
            Q('i2', L('Perché tenere i contenuti importanti nell’HTML?', 'Why keep important content in the HTML?'), [L('Il rendering del JavaScript è più lento e limitato', 'JavaScript rendering is slower and limited'), L('Il JavaScript è vietato dai motori', 'JavaScript is banned by engines'), L('L’HTML pesa sempre meno', 'HTML always weighs less'), L('Per non usare il CSS', 'To avoid using CSS')], 0, L('Il rendering arriva dopo.', 'Rendering comes later.')),
            Q('i3', L('A che cosa servono i dati strutturati JSON-LD?', 'What is JSON-LD structured data for?'), [L('Descrivere esplicitamente il contenuto', 'Describing the content explicitly'), L('Rendere la pagina più colorata', 'Making the page more colourful'), L('Bloccare i crawler', 'Blocking crawlers'), L('Comprimere le immagini', 'Compressing images')], 0, L('schema.org dà il vocabolario.', 'schema.org gives the vocabulary.')),
        ], task('html', L('Prepara la `<head>` di una pagina: un `<title>` e una `<meta name="description">` con un testo.', 'Prepare a page’s `<head>`: a `<title>` and a `<meta name="description">` with some text.'), "<head>\n  \n</head>", [re('<title>[^<]+</title>', L('C’è un titolo', 'There is a title')), re('<meta\s+name="description"\s+content="[^"]+"', L('C’è la description', 'There is the description'))], '', "<head>\n  <title>Pizza napoletana: la ricetta</title>\n  <meta name=\"description\" content=\"Impasto, lievitazione e cottura della vera pizza napoletana.\">\n</head>"), [
            dMatch(pMatch(), [['<title>', L('Titolo nel risultato di ricerca', 'Title in the search result')], ['meta description', L('Testo sotto il titolo', 'Text under the title')], ['alt', L('Descrive un’immagine', 'Describes an image')], ['JSON-LD', L('Dati strutturati', 'Structured data')]], L('Che cosa legge il motore.', 'What the engine reads.')),
            dFlash(pFlash(), [[L('Google può eseguire il JavaScript delle pagine', 'Google can run pages’ JavaScript'), true], [L('L’indice invertito si scorre pagina per pagina a ogni ricerca', 'The inverted index is scanned page by page on each search'), false], [L('Il testo dei link aiuta a capire la pagina di destinazione', 'Link text helps understand the target page'), true], [L('L’attributo alt è ignorato da tutti', 'The alt attribute is ignored by everyone'), false]], L('Dall’HTML all’indice.', 'From HTML to the index.')),
        ]),
        lesson('ranking', L('Ranking e SEO tecnica', 'Ranking and technical SEO'), [
            P('Quando cerchi, il motore prende dall’indice le pagine candidate e le **ordina** con centinaia di segnali: **pertinenza** rispetto alla domanda (anche il significato, non solo le parole), **qualità e autorevolezza** (per esempio i link da altri siti, l’idea del PageRank), **esperienza della pagina** (velocità, mobile, HTTPS), freschezza, lingua e posizione dell’utente.', 'When you search, the engine takes candidate pages from the index and **sorts** them with hundreds of signals: **relevance** to the query (meaning too, not just words), **quality and authority** (for example links from other sites, the idea behind PageRank), **page experience** (speed, mobile, HTTPS), freshness, the user’s language and location.'),
            P('La **SEO tecnica** rende il sito facile da scansionare e capire: URL leggibili, link interni, un solo `<h1>` chiaro, pagine veloci (Core Web Vitals), versione mobile completa, `hreflang` per le lingue, nessun contenuto duplicato senza canonical. Trucchi come testo nascosto o link comprati vengono penalizzati.', '**Technical SEO** makes the site easy to crawl and understand: readable URLs, internal links, a single clear `<h1>`, fast pages (Core Web Vitals), a complete mobile version, `hreflang` for languages, no duplicate content without canonical. Tricks such as hidden text or bought links are penalised.'),
            Tip('Sempre più ricerche mostrano risposte generate dall’AI: le pagine chiare, ben strutturate e affidabili sono anche quelle che queste risposte citano.', 'More and more searches show AI-generated answers: clear, well-structured and trustworthy pages are also the ones these answers cite.'),
        ], [
            Q('k1', L('Che cosa misurava l’idea del PageRank?', 'What did the PageRank idea measure?'), [L('L’autorevolezza tramite i link ricevuti', 'Authority through received links'), L('Il numero di parole della pagina', 'The page’s word count'), L('La velocità del server', 'The server’s speed'), L('I colori del sito', 'The site’s colours')], 0, L('Un link è come un voto.', 'A link is like a vote.')),
            Q('k2', L('Quale pratica viene penalizzata?', 'Which practice is penalised?'), [L('Testo nascosto e link comprati', 'Hidden text and bought links'), L('Usare HTTPS', 'Using HTTPS'), L('URL leggibili', 'Readable URLs'), L('Pagine veloci', 'Fast pages')], 0, L('Niente scorciatoie.', 'No shortcuts.')),
            Q('k3', L('A che cosa serve `hreflang`?', 'What is `hreflang` for?'), [L('Indicare le versioni in altre lingue', 'Pointing to versions in other languages'), L('Cambiare il font', 'Changing the font'), L('Vietare la scansione', 'Disallowing crawling'), L('Comprimere l’HTML', 'Compressing HTML')], 0, L('Il risultato giusto per ogni lingua.', 'The right result for each language.')),
        ], task('text', L('Scrivi tre interventi di SEO tecnica per un sito lento e poco trovato, uno per riga con `-`, tra cui uno sulla **velocità** e uno sui **link interni**.', 'Write three technical SEO fixes for a slow, hard-to-find site, one per line with `-`, including one about **speed** and one about **internal links**.'), "- \n- \n- ", [re('^-\s*\S.*\n-\s*\S.*\n-\s*\S', L('Tre interventi', 'Three fixes')), re('veloc|speed|fast|rapid|web vitals|immagini|images', L('La velocità', 'Speed')), re('link intern|internal link', L('I link interni', 'Internal links'))], '', "- comprimere le immagini per aumentare la velocità\n- aggiungere link interni verso le pagine profonde\n- inviare una sitemap XML"), [
            dMatch(pMatch(), [[L('Pertinenza', 'Relevance'), L('Risponde alla domanda', 'Answers the query')], [L('Autorevolezza', 'Authority'), L('Link da altri siti', 'Links from other sites')], ['Core Web Vitals', L('Velocità e stabilità', 'Speed and stability')], ['hreflang', L('Versioni per lingua', 'Versions per language')]], L('I segnali del ranking.', 'Ranking signals.')),
            dFlash(pFlash(), [[L('La velocità della pagina è un segnale di ranking', 'Page speed is a ranking signal'), true], [L('Più parole chiave ripetute danno sempre il primo posto', 'More repeated keywords always give first place'), false], [L('Un solo h1 chiaro aiuta a capire la pagina', 'A single clear h1 helps understand the page'), true], [L('I link comprati sono premiati', 'Bought links are rewarded'), false]], L('Qualità prima dei trucchi.', 'Quality before tricks.')),
        ]),
        lesson('structured', L('Dati strutturati e Search Console', 'Structured data and Search Console'), [
            P('I **dati strutturati** descrivono il contenuto di una pagina in un formato che i motori capiscono: un articolo, una ricetta, un evento, un corso. Si scrivono in **JSON-LD** con il vocabolario di **schema.org** e possono produrre risultati arricchiti (stelle, date, prezzi).', '**Structured data** describes a page’s content in a format engines understand: an article, a recipe, an event, a course. It is written in **JSON-LD** with the **schema.org** vocabulary and can produce rich results (stars, dates, prices).'),
            C('<script type="application/ld+json">
{
  "@context": "https://schema.org",
  "@type": "Course",
  "name": "HTML base",
  "description": "Le basi dell’HTML a livelli",
  "provider": { "@type": "Organization", "name": "Fucina" }
}
</script>', 'html'),
            P('**Google Search Console** mostra come Google vede il sito: pagine indicizzate o escluse (e perché), query che portano visite, errori dei dati strutturati, problemi su mobile. Lì si invia la sitemap e si chiede di indicizzare di nuovo una pagina corretta.', '**Google Search Console** shows how Google sees the site: pages indexed or excluded (and why), queries that bring visits, structured data errors, mobile issues. There you submit the sitemap and ask to reindex a fixed page.'),
        ], [
            Q('sd1', L('In che formato si scrivono di solito i dati strutturati?', 'In what format is structured data usually written?'), ['JSON-LD', 'CSV', 'XML-RPC', 'YAML'], 0, L('Dentro uno `<script type="application/ld+json">`.', 'Inside a `<script type="application/ld+json">`.')),
            Q('sd2', L('Quale vocabolario si usa?', 'Which vocabulary is used?'), ['schema.org', 'w3schools', 'MDN', 'OpenAPI'], 0, L('Tipi come Course, Article, Event.', 'Types like Course, Article, Event.')),
            Q('sd3', L('Che cosa trovi in Search Console?', 'What do you find in Search Console?'), [L('Pagine indicizzate, query ed errori', 'Indexed pages, queries and errors'), L('Il codice sorgente di Google', 'Google’s source code'), L('Le password degli utenti', 'Users’ passwords'), L('Gli annunci a pagamento soltanto', 'Paid ads only')], 0, L('Lo sguardo di Google sul sito.', 'Google’s view of the site.')),
        ], task('html', L('Aggiungi uno `<script type="application/ld+json">` con `"@type": "Course"` e `"name": "CSS base"`.', 'Add a `<script type="application/ld+json">` with `"@type": "Course"` and `"name": "CSS base"`.'), '', [has('script[type="application/ld+json"]', L('C’è lo script JSON-LD di tipo Course', 'The Course JSON-LD script is there'), 'Course'), has('script[type="application/ld+json"]', L('Il nome del corso è giusto', 'The course name is right'), 'CSS base')], '', "<script type=\"application/ld+json\">\n{ \"@context\": \"https://schema.org\", \"@type\": \"Course\", \"name\": \"CSS base\" }\n</script>"), [
            dMatch(pMatch(), [['JSON-LD', L('Formato dei dati strutturati', 'Structured data format')], ['schema.org', L('Vocabolario dei tipi', 'Type vocabulary')], ['@type', L('Che cosa descrive', 'What it describes')], ['Search Console', L('Come Google vede il sito', 'How Google sees the site')], [L('Risultato arricchito', 'Rich result'), L('Stelle, date, prezzi', 'Stars, dates, prices')]], L('Parlare ai motori.', 'Talking to engines.')),
            dFlash(pFlash(), [[L('I dati strutturati possono dare risultati arricchiti', 'Structured data can give rich results'), true], [L('JSON-LD va scritto nel file robots.txt', 'JSON-LD goes in robots.txt'), false], [L('In Search Console si invia la sitemap', 'The sitemap is submitted in Search Console'), true], [L('Search Console garantisce il primo posto', 'Search Console guarantees first place'), false]], L('Visibilità con metodo.', 'Visibility with method.')),
        ]),
    ],
];
